+import { readFileSync, writeFileSync, existsSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

+const STORE_PATH = join(process.cwd(), ".session-store.json");
 const store = new Map<string, Entry>();

+const loadStore = (): void => {
+  if (!existsSync(STORE_PATH)) return;
+  try {
+    const data = readFileSync(STORE_PATH, "utf-8");
+    const parsed = JSON.parse(data) as Record<string, Entry>;
+    store.clear();
+    for (const [key, entry] of Object.entries(parsed)) {
+      store.set(key, entry);
+    }
+  } catch {
+    // Ignore parse errors, start with empty store
+  }
+};
+
+const persistStore = (): void => {
+  const data: Record<string, Entry> = {};
+  for (const [key, entry] of store) {
+    data[key] = entry;
+  }
+  writeFileSync(STORE_PATH, JSON.stringify(data));
+};
+
+loadStore();
+
 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  persistStore();
 };

